  "poster": {
    "aspect_ratio": "A0-portrait",
    "audience": "academic-conference",
    "tone": "data-forward, professional",
    "venue": "IMF-World Bank Annual Meetings Research Symposium"
  },
  "brief": {
    "title": "Global Economy in the Shadow of War: IMF World Economic Outlook Trends 2024–2026",
    "one_liner": "A synthesis of IMF World Economic Outlook projections from 2024 through 2026, tracking the trajectory of global growth, inflation, and evolving policy priorities amid rising geopolitical uncertainty.",
    "goal": "The viewer should understand how global growth projections have evolved over the past two years, grasp the key downside risks (trade policy, geopolitical tensions, inflation persistence), and recognize the IMF's shifting policy recommendations from monetary pivot to defense-spending trade-offs."
  },
  "sections": [
    {
      "id": "growth-trajectory",
      "title": "Global Growth Projections: A Narrow Band of Mediocrity",
      "objective": "Present the timeline of IMF global growth forecasts from mid-2024 through April 2026, highlighting the narrow 3.0–3.3% band and the persistent underperformance relative to the pre-pandemic average of ~3.8%."
    },
    {
      "id": "key-risks",
      "title": "Dominant Downside Risks",
      "objective": "Summarize the recurring and emerging risk factors identified across WEO editions—tariff escalation, geopolitical tensions, technology re-evaluation, and persistent services inflation."
    },
    {
      "id": "inflation-dynamics",
      "title": "Inflation Outlook and Monetary Policy",
      "objective": "Show the disinflation trend globally while highlighting the US exception of slower return to target, and the implications for the monetary policy pivot."
    },
    {
      "id": "policy-evolution",
      "title": "Evolving Policy Priorities",
      "objective": "Trace how IMF policy recommendations shifted from fiscal sustainability and buffer rebuilding (2024) through structural reforms and labor market inclusion (early 2025) to agile defense-spending management (2026)."
    },
    {
      "id": "thematic-focus",
      "title": "Special Themes Across WEO Editions",
      "objective": "Highlight the rotating analytical themes—industrial policy effectiveness, social acceptability of reforms, demographic challenges, and gender/migration labor market integration."
    }
  ],
  "metrics": [
    {
      "label": "Global Growth 2025 (projected)",
      "value": "3.0%",
      "source": "WEO July 2025 Update"
    },
    {
      "label": "Global Growth 2026 (projected)",
      "value": "3.3%",
      "source": "WEO January 2026 Update"
    },
    {
      "label": "Global Growth 2027 (projected)",
      "value": "3.2%",
      "source": "WEO January 2026 Update"
    },
    {
      "label": "Number of WEO editions reviewed",
      "value": "8",
